import mongoose from "mongoose";

const paymentSchema = new mongoose.Schema(
  {
    // User who initiated the payment
    user: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "User",
      required: true,
    },

    // Course being purchased
    course: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Course",
      required: true,
    },

    // Unique order ID generated by Razorpay
    razorpayOrderId: {
      type: String,
      required: true,
      unique: true,
    },

    // Filled in when we receive a payment ID
    razorpayPaymentId: {
      type: String,
      default: null,
    },

    // Amount in paise, not rupees
    amount: {
      type: Number,
      required: true,
      min: 1,
    },

    currency: {
      type: String,
      default: "INR",
      enum: ["INR"],
    },

    // "created" means an order exists, not that payment succeeded
    status: {
      type: String,
      enum: ["created", "paid", "failed", "refunded"],
      default: "created",
    },
  },
  { timestamps: true }
);

const Payment = mongoose.model("Payment", paymentSchema);

export default Payment;